 final Runnable tick=new Runnable(){public void run(){long remain=Math.max(0,(deadline-SystemClock.elapsedRealtime()+999)/1000); if(timerLabel!=null){String label=remain>0?"Descanso  "+remain/60+":"+String.format(Locale.US,"%02d",remain%60):"Descanso concluído";if(!label.contentEquals(timerLabel.getText()))timerLabel.setText(label);} if(remain>0)handler.postDelayed(this,250); else if(deadline>0){deadline=0; android.media.ToneGenerator tone=new android.media.ToneGenerator(android.media.AudioManager.STREAM_NOTIFICATION,65);tone.startTone(android.media.ToneGenerator.TONE_PROP_ACK,300);handler.postDelayed(()->tone.release(),500);}}};
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("training",MODE_PRIVATE);loadCatalog();loadPlan();selected=prefs.getInt("day",Math.min(4,Math.max(0,Calendar.getInstance().get(Calendar.DAY_OF_WEEK)-2)));selected=Math.min(selected,days.length-1);if(b!=null)deadline=b.getLong("deadline",0);load();show();syncPlan(false);}
