 void show(){prefs.edit().putInt("day",selected).apply();base("SetHarbor");body.addView(text(activePlan.optString("title","Meu treino"),14,muted));Spinner selector=new Spinner(this);selector.setContentDescription("Dia do treino");selector.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,days));selector.setSelection(selected);body.addView(selector);selector.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){} public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){if(position!=selected){selected=position;load();show();}}});body.addView(text(focuses[selected],18,green));
 Spinner phase=new Spinner(this);phase.setContentDescription("Modo do treino");phase.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Semana 1 · 2 séries · RIR 3–4","Semana 2 · volume completo · RIR 2","Normal · volume completo · RIR 1–2"}));phase.setSelection(prefs.getInt("phase",0));body.addView(phase);phase.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(pos!=prefs.getInt("phase",0)){prefs.edit().putInt("phase",pos).apply();show();}}});
 LinearLayout timer=card();timerLabel=text("Descanso",18,green);timer.addView(timerLabel);LinearLayout durations=new LinearLayout(this);for(int sec:new int[]{60,90,120})durations.addView(button(sec+" s",()->{deadline=SystemClock.elapsedRealtime()+sec*1000;handler.removeCallbacks(tick);tick.run();}),new LinearLayout.LayoutParams(0,-2,1));timer.addView(durations);timer.addView(button("Parar",()->{deadline=0;handler.removeCallbacks(tick);timerLabel.setText("Descanso");}));if(deadline>0){handler.removeCallbacks(tick);tick.run();}
 for(int e=0;e<names[selected].length;e++)addExercise(e);

 body.addView(text("Progrida quando atingir o topo da faixa em todas as séries. Confira a unidade de carga nos detalhes. Em exercícios assistidos, reduza a assistência para progredir; peso corporal usa 0 kg sem carga adicional. Aquecimentos não entram nas séries.",13,muted));body.addView(button("Concluir e salvar treino",()->finishWorkout()));body.addView(button("Histórico de treinos",()->history()));body.addView(button("Importar ficha de treino",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,44);}));body.addView(button("Atualização online",()->configureSync()));body.addView(button("Exportar backup",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"meu-treino-backup.json");startActivityForResult(i,42);}));body.addView(button("Restaurar backup",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,43);}));}
